<script lang="ts">
    import type { Component, Snippet } from "svelte";
    import Icon from './Icon.svelte';
	import { fly } from "svelte/transition";
	import { popBezier, popBezierInverse } from "../util/transitions.js";

    /**
     * @description
     * A component that displays an icon with a possible label. It can also have a click event.
     * The button has a padding of 0.75em by default to make it easier to tap on mobile devices. The padding can be changed using the `--padding` CSS variable.
     * Icon and text color will be inherited from the parent element.
     * @cssprop --padding - The padding of the icon button. (Default: var(--space-sm))
     * @example
     * <script>
     * import Copy from 'lutra/Icons/Copy.svelte';
     * import Link from 'lutra/Icons/Link.svelte';
     * <\/script>
     * <IconButton icon={Link} onclick={() => alert('clicked')} />
     * <IconButton icon={Copy} onclick={() => alert('clicked')}>Copy</IconButton>
     */
    let {
        icon,
        disabled,
        children,
        onclick,
        mask = true,
        scale = 'md'
    }: {
        /** The icon to display. */
        icon: string | Component;
        /** The children to display. */
        children?: Snippet,
        /** The onclick event. */
        onclick?: (event: MouseEvent) => void,
        /** Whether the button is disabled. */
        disabled?: boolean,
        /** Whether to mask the content. */
        mask?: boolean,
        /** Size variant controlling font-size. Icon and padding scale automatically. */
        scale?: 'xs' | 'sm' | 'md' | 'lg' | 'xl'
    } = $props();

</script>

{#snippet inside()}
    <span class="IconMask" class:mask>
        {#key icon}
            <span class="IconContent" in:fly={{ duration: 250, y: -32, easing: popBezier }} out:fly={{ duration: 250, y: 32, easing: popBezierInverse }}>
                <Icon {icon} --cursor="pointer" />
                {#if children}
                    <span class="Text">
                        {@render children()}
                    </span>
                {/if}
            </span>
        {/key}
    </span>
{/snippet}

{#if onclick}
    <button type="button" {disabled} class="IconButton {scale}" {onclick}>
        {@render inside()}
    </button>
{:else}
    <span class="IconButton {scale}">
        {@render inside()}
    </span>
{/if}

<style>
    .IconButton {
        display: inline-flex;
        align-items: stretch;
        color: inherit;
        opacity: 1;
        background-color: var(--field-background-color, transparent);
        transition: background-color var(--transition-duration-fast);
        border-radius: var(--field-border-radius);
    }
    .IconButton:hover,
    .IconButton:focus-visible {
        background-color: var(--menu-background-color-hover);
    }
    .IconButton:active {
        scale: 1;
    }
    button.IconButton {
        border: none;
        background: none;
        cursor: pointer;
    }
    .IconMask {
        height: 100%;
        padding-inline: calc(var(--padding, var(--space-sm)) * 0.8);
        padding-block: calc(var(--padding, var(--space-sm)) * 0.8);
        display: inline-grid;
        gap: var(--space-xs);
        grid-template: "icon";
        align-items: center;
    }
    .IconMask.mask {
        -webkit-mask-image: linear-gradient(to bottom, transparent, black 35%, black 65%, transparent);
        mask-image: linear-gradient(to bottom, transparent, black 35%, black 65%, transparent);
    }
    .IconContent {
        grid-area: icon;
        display: inline-flex;
        gap: var(--space-xs);
        align-items: center;
    }

    .IconButton.xs { font-size: var(--font-size-xs); }
    .IconButton.sm { font-size: var(--font-size-sm); }
    .IconButton.lg { font-size: var(--font-size-h5); }
    .IconButton.xl { font-size: var(--font-size-h4); }
</style>